{
  "findings": [
    {
      "check_id": "CKV_GCP_14",
      "title": "Ensure all Cloud SQL database instance have backup configuration enabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "Backup configuration is disabled for the Cloud SQL database instance"
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Ensure all Cloud SQL database instance requires all incoming connections to use SSL",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The Cloud SQL database instance does not require SSL for incoming connections"
    },
    {
      "check_id": "CKV_GCP_60",
      "title": "Ensure Cloud SQL database does not have public IP",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The Cloud SQL database instance has a public IP address"
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "Ensure PostgreSQL database 'log_lock_waits' flag is set to 'on'",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_lock_waits' flag is not set to 'on' for the PostgreSQL database"
    }
  ],
  "patched_code": "resource "google_sql_database_instance" "metadata_database" {
  name             = "digital-library-content-management-platform-db-metadata"
  database_version = "POSTGRES_14"
  region           = var.region
  deletion_protection = false
  settings {
    tier = "db-f1-micro"
    backup_configuration {
      enabled = true
    }
    ip_configuration {
      ipv4_enabled    = false
      require_ssl     = true
    }
    database_flags {
      name  = "log_lock_waits"
      value = "on"
    }
    database_flags {
      name  = "log_checkpoints"
      value = "on"
    }
    database_flags {
      name  = "log_connections"
      value = "on"
    }
    database_flags {
      name  = "log_disconnections"
      value = "on"
    }
    database_flags {
      name  = "log_min_error_statement"
      value = "ERROR"
    }
  }
}",
  "fix_summary": "Enabled backup configuration, disabled public IP, required SSL for incoming connections, and set 'log_lock_waits' to 'on'. Additionally, enabled logging for checkpoints, connections, and disconnections, and set log level to ERROR."
}
